INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('ace9120b-4309-4909-881e-cde9f799c3e0', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'Jaime deseja criar um município e, para tanto, necessita saber os requisitos constitucionais. Considerando apenas as disposições da Constituição, assinale a alternativa que NÃO apresenta um requisito para a criação de um Município.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Pontão - RS / Fisioterapeuta / Questão: 22', 'O art. 18, §4º, exige: (i) consulta prévia às populações envolvidas, mediante plebiscito; (ii) divulgação dos Estudos de Viabilidade Municipal, na forma da lei; (iii) lei estadual, dentro do período determinado por Lei Complementar Federal — e não estadual, como diz a alternativa "b". Trata-se de pegadinha comum: o período é definido por lei complementar de âmbito federal, cabendo à lei estadual apenas efetivar a criação do município dentro desse prazo.', 1, true),
('d79ae3d9-c635-4d62-a789-fe0b8275722d', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'A Constituição Federal concede autonomia política, administrativa e financeira aos Municípios. Nesse sentido, tem-se que, segundo sua Lei Orgânica, o Município de Porto Alegre é classificado juridicamente como:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura de Porto Alegre - RS / Assistente Administrativo / Questão: 24', 'Os Municípios, assim como a União, os Estados e o Distrito Federal, são entes da federação e, portanto, pessoas jurídicas de direito público interno, dotadas de autonomia política, administrativa e financeira (art. 18, caput). Não se confundem com autarquias (que são pessoas jurídicas de direito público criadas por lei, mas sem autonomia política) nem com pessoas jurídicas de direito privado.', 2, true),
('9ac459af-dd08-4424-b349-f5da69abf702', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'A organização político-administrativa da República Federativa do Brasil compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos, sendo a Capital Federal:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Três de Maio - RS / Eletricista / Questão: 30', 'O art. 18, §1º, dispõe: "Brasília é a Capital Federal". A escolha de Brasília, no Planalto Central, decorreu de um projeto de interiorização do desenvolvimento nacional, concretizado com a inauguração da cidade em 1960 e posteriormente confirmado pelo texto constitucional de 1988.', 3, true),
('e2052d78-7fec-4bb3-a0cd-3b7bc1c1f4d4', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'Uma comunidade deseja se desmembrar do território do atual Município X e criar o Município Y. Qual é o instrumento legislativo indicado para a realização desse desmembramento?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Cruzaltense - RS / Auxiliar de Saúde Bucal / Questão: 20', 'O art. 18, §4º, exige que a criação, incorporação, fusão e desmembramento de Municípios se façam por lei estadual, dentro do período determinado por Lei Complementar Federal, precedida de plebiscito às populações envolvidas e de divulgação dos Estudos de Viabilidade Municipal. Não se trata de matéria de emenda constitucional, decreto legislativo, lei delegada, tampouco de decisão judicial.', 4, true),
('cec682e6-e1e4-4ce8-8c14-9913ed2b1cae', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'De acordo com a Constituição Federal, é vedado à União, aos Estados, ao Distrito Federal e aos Municípios:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Cruzaltense - RS / Auxiliar de Serviços Gerais / Questão: 16', 'Novamente o art. 19, II, é a base da resposta: é vedado a todos os entes federativos "recusar fé aos documentos públicos". As demais alternativas tratam de atividades típicas do poder público, sem qualquer vedação constitucional.', 5, true),
('fae3904a-b530-4c98-9fe9-85b9d163f7d9', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'Sobre a criação, a incorporação, a fusão e o desmembramento de município, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2023 / Prefeitura de Farroupilha - RS / Procurador Municipal / Questão: 33', 'O art. 18, §4º, é claro: a criação, a incorporação, a fusão e o desmembramento de Municípios dependem de consulta prévia, mediante plebiscito, às populações dos Municípios envolvidos, após a divulgação dos Estudos de Viabilidade Municipal, apresentados e publicados na forma da lei. As demais alternativas inventam requisitos (autorização de Governador, emenda à Constituição Estadual) que não constam do texto constitucional, ou restringem indevidamente o instituto às regiões metropolitanas.', 6, true),
('232fe601-c104-42ba-b9f6-35347bfd79e2', '95430ed1-50c7-4c72-8a87-0a326adff5c7', 'Com base nos termos da Constituição Federal, os Territórios Federais integram a União, e sua criação, transformação em Estado ou reintegração ao Estado de origem serão reguladas em:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Prefeitura de Restinga Seca - RS / Procurador Jurídico / Questão: 29', 'O art. 18, §2º, dispõe que "os Territórios Federais integram a União, e sua criação, transformação em Estado ou reintegração ao Estado de origem serão reguladas em lei complementar". Trata-se de matéria que exige o rito qualificado da lei complementar (aprovação por maioria absoluta), dada sua relevância para a estrutura federativa.', 7, true);
